// 新代码：输出与其他平台完全一致的格式，并增加 engagement_score
try {
  const tweetObject = $input.item.json;

  // 从推文的公开指标(public_metrics)中计算一个综合的互动分数
  // 同时增加安全检查，防止某些指标不存在时报错
  const metrics = tweetObject.public_metrics || {};
  const likeCount = metrics.like_count || 0;
  const retweetCount = metrics.retweet_count || 0;
  const replyCount = metrics.reply_count || 0;
  const quoteCount = metrics.quote_count || 0;
  const engagementScore = likeCount + retweetCount + replyCount + quoteCount;

  // 构建与其他平台格式完全一致的result对象
  const result = {
    source_weight: 0.9,                        // 权重
    source_type: 'twitter',                    // 来源类型
    content: tweetObject.text,                 // 推文内容
    url: `https://x.com/anyuser/status/${tweetObject.id}`, // 推文链接
    engagement_score: engagementScore          // 互动分数
  };

  return { json: result };

} catch (error) {
  console.error('处理推文JSON时出错:', error);
  return { json: { error: '处理推文JSON失败', raw_data: $input.item.json } };
}

// 最终代码：在"Run Once for All Items"模式下，处理所有批次并返回所有结果

// 1. 创建一个空数组，用来存放所有批次解析后的最终结果。
const allParsedItems = [];

// 2. 遍历所有输入的项目（您这里的10个批次）。
//    $input.all() 可以获取全部的输入项。
for (const batchItem of $input.all()) {
  try {
    const contentString = batchItem.json.text;
    if (!contentString) continue; // 如果某个批次的text为空，则跳过

    const cleanedContent = contentString.replace(/```json/g, '').replace(/```/g, '').trim();

    // 3. 解析当前批次中的JSON字符串。
    const itemsInBatch = JSON.parse(cleanedContent);

    // 4. 将解析出的项目（一个数组）添加到我们最终的总结果数组中。
    if (Array.isArray(itemsInBatch)) {
      allParsedItems.push(...itemsInBatch);
    }

  } catch (error) {
    // 如果某个批次解析失败，在控制台打印错误并继续处理下一个批次。
    console.error(`一个批次解析失败。错误: ${error.message}. 批次内容: ${batchItem.json.text}`);
  }
}

// 5. 循环结束后，将包含了所有结果的总数组，格式化成n8n需要的格式并返回。
return allParsedItems.map(item => ({ json: item }));

try {
  const errorInfo = {
    error: '工作流执行出错',
    timestamp: new Date().toISOString(),
    node_error: $input.item(0).json.error || '未知错误',
    analysis_id: $('Analysis Parameters').item.json.analysis_id || 'unknown'
  };

  console.error('工作流错误:', errorInfo);
  return { json: errorInfo };
} catch (e) {
  return { 
    json: { 
      error: '严重错误: 错误处理节点也失败了',
      timestamp: new Date().toISOString()
    } 
  };
}

// 新代码：增加了清理步骤
try {
  // 1. 从 'text' 字段获取AI返回的原始字符串
  let contentString = $input.item.json.text;

  // 2. **新增的关键步骤：清理字符串，去掉AI可能添加的markdown标记**
  contentString = contentString.replace(/```json/g, '').replace(/```/g, '').trim();

  // 3. 解析这个干净的字符串
  const aiResults = JSON.parse(contentString);

  // 4. 从上游的"聚合1"节点获取原始数据项
  const originalItems = $('Aggregate: Relevant Items').all();

  // 5. 检查AI输出是否是我们期望的格式
  if (!aiResults.analyses || !Array.isArray(aiResults.analyses)) {
    throw new Error("AI output is not in the expected format: { \"analyses\": [...] }");
  }

  // 6. 将AI分析结果与原始数据进行匹配和合并
  const enrichedAnalyses = aiResults.analyses.map(analysis => {
    const originalItem = originalItems.find(item => item.json.url === analysis.original_url);

    return {
      json: {
        ...analysis,
        source_info: originalItem ? {
          type: originalItem.json.source_type,
          weight: originalItem.json.source_weight,
          engagement_score: originalItem.json.engagement_score || 0
        } : {
          type: 'unknown',
          url: analysis.original_url
        },
        analysis_timestamp: new Date().toISOString()
      }
    };
  });

  // 7. 返回包含所有合并后结果的数组
  return enrichedAnalyses;

} catch (error) {
  console.error('成型分析结果节点错误:', error);
  return [{ 
    json: { 
      error: `成型分析结果失败: ${error.message}`,
      raw_content: $input.item.json.text || 'No raw content available'
    } 
  }];
}

